#' Book 1 teaching cohort (simulated)
#'
#' A simulated school health cohort of about 3,500 children followed through
#' annual examinations from 2018 to 2025 (no examinations in 2021) at three
#' sites, ages 18 months to 18 years. Generated by
#' `wgh_simulate(4000, preset = "wgh_like", seed = 2024)`. The cohort
#' resembles the school health cohort of the research program so analyses give tables and
#' figures similar to the papers. It is not real data.
#'
#' @format A data frame with one row per visit:
#' \describe{
#'   \item{pid}{Child identifier}
#'   \item{sex}{Factor, Male or Female}
#'   \item{site}{Site (Site1, Site2, Site3)}
#'   \item{dob, examdate}{Date of birth and of examination}
#'   \item{yearvisit}{School year of the examination}
#'   \item{age}{Exact age in years}
#'   \item{height, weight, bmi}{cm, kg, kg/m2}
#'   \item{haz, waz, baz}{WHO z-scores (weight-for-age only to 10 years)}
#' }
#' @source Simulated with [wgh_simulate()]. See `data-raw/datasets.R`.
#' @examples
#' head(growdat)
#' table(growdat$sex, growdat$site)
#' # Wrap in the data contract, computing age from the two dates
#' gd <- wgh_data(growdat, id = "pid", sex = "sex", dob = "dob", date = "examdate",
#'                height = "height", weight = "weight", site = "site")
#' gd
"growdat"

#' Book 1 raw export with data-entry errors (simulated)
#'
#' `growdat` before cleaning, as a school health information system might
#' export it, with errors injected by [wgh_add_messiness()] (heights in
#' metres, weights in grams, swapped values, digit slips, duplicated rows,
#' inconsistent sex codes, stray spaces, wrong examination years and missing
#' values). The attribute `"messiness_log"` lists every injected error.
#' @format A data frame like [growdat] without the z-score and BMI columns.
#' @source `wgh_add_messiness(growdat, rate = 0.03, seed = 2024)`.
#' @examples
#' head(growdat_raw)
#' # Clean the problems added on purpose and see what was changed
#' cl <- wgh_clean(growdat_raw)
#' head(attr(cl, "cleaning_log"))
"growdat_raw"

#' Book 2 teaching cohort, small version (simulated)
#'
#' A random 3,000-child subset of the full Book 2 cohort generated by
#' `wgh_simulate(30000, preset = "wgh_like", seed = 2026, style = "book2")`.
#' Column names follow Book 2 (`schoolyear`, `bmiz`). The full cohort is
#' available with [wgh_download()]. `growdat2_mini_truth` holds the true
#' child-level parameters (size, timing, intensity, phenotype, APHV, PHV).
#' @format Data frames. See [wgh_simulate()] for the columns.
#' @examples
#' head(growdat2_mini)
#' length(unique(growdat2_mini$pid))
#' # True SITAR parameters of the simulated children
#' head(growdat2_mini_truth)
"growdat2_mini"

#' @rdname growdat2_mini
"growdat2_mini_truth"

#' Clinical cases with sparse, irregular visits (simulated)
#'
#' Sixty children seen in a paediatric clinic at irregular intervals, with
#' referral group and gestational age, for Book 1 Part II and broken-stick
#' examples. Generated by `wgh_simulate_clinical_cases(60, seed = 2024)`.
#' @format A data frame with `pid`, `sex`, `group`, `gestational_age`, `age`,
#'   `age_corrected`, `height`, `weight`, `bmi`, `haz`, `waz`, `baz`.
#' @examples
#' head(clinical_cases)
#' table(clinical_cases$group)
"clinical_cases"
